package com.bheemnagartimes.news.service;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.util.StringUtils;import org.springframework.web.multipart.MultipartFile;import java.io.IOException;import java.nio.file.*;import java.util.UUID;
@Service public class FileStorageService{private final Path uploadDir;public FileStorageService(@Value("${news.upload-dir:./data/uploads}")String dir)throws IOException{uploadDir=Paths.get(dir).toAbsolutePath().normalize();Files.createDirectories(uploadDir);}public String store(MultipartFile file)throws IOException{if(file==null||file.isEmpty())return null;String n=StringUtils.cleanPath(file.getOriginalFilename()==null?"image":file.getOriginalFilename());String ext="";int i=n.lastIndexOf('.');if(i>=0)ext=n.substring(i).toLowerCase();if(!ext.matches("\\.(png|jpe?g|webp)$"))throw new IllegalArgumentException("केवल PNG, JPG, JPEG या WEBP image स्वीकार है।");Path target=uploadDir.resolve(UUID.randomUUID()+ext).normalize();Files.copy(file.getInputStream(),target);return "/uploads/"+target.getFileName();}}